mapper.select:
select request_id from wf_runtime_event_request
where status in ('PROCESSED','FAILED') and complete_time <= #{cutoffTime}
order by complete_time,request_id limit #{limit} for update skip locked

mapper.delete:
delete from wf_runtime_event_request
where request_id in
#{requestId}
  and status in ('PROCESSED','FAILED') and complete_time <= #{cutoffTime}
